// DINERO 30-oct-2026 15:00 · Firmar de aval (método V2)
// Metáfora: tu firma se vuelve una CADENA dorada que te ata al monstruo de la deuda; el monstruo
// crece con recargos y puede saltar directo hacia ti.
// Sitios: A = la mesa del banco con el contrato (azul marino, lámpara arriba a la izquierda);
//         B = el cuarto del monstruo de la deuda (azul más oscuro, luz roja baja solo en pérdidas).
import React from 'react';
import {AbsoluteFill, Easing, interpolate, clamp, useS, en, golpe, sacudida, Etiqueta, Contador, Carita, Camara, Destello, Ondas, Estela, FONT} from './kit';

export const SUBS = {acento: '#FFC83D'};

const ORO = '#FFC83D';
const ROJO = '#FF4D4D';

const T_FIRMAR = en('firmar');
const T_CARO = en('caro');
const T_PRIMO = en('primo');
const T_QUINCE = en('quince');
const T_CARRO = en('carro');
const T_FIRMAS = en('firmas');
const T_FIRMA = en('firma');
const T_ATADA = en('atada');
const T_DEJA = en('deja');
const T_COMPLETA = en('completa');
const T_ESTADOS = en('estados');
const T_DIRECTO = en('directo');
const T_RECARGOS = en('recargos');
const T_COBRANZA = en('cobranza');
const T_HISTORIAL = en('historial');
const T_FIRMA2 = en('Firma', 2);
const T_QUINCE2 = en('quince', 2);
const T_CONTRATO = en('contrato');
const T_AVISEN = en('avisen');
const T_ENVIA = en('Envíaselo');
const T_FAMILIA = en('familia');

const FondoSitio: React.FC<{oscuro: boolean}> = ({oscuro}) => {
  const {s} = useS();
  const c = oscuro ? ['#1a2c55', '#0b1530', '#03060f'] : ['#27497f', '#112452', '#050b1c'];
  return (
    <AbsoluteFill style={{background: `radial-gradient(ellipse at 26% 20%, ${c[0]} 0%, ${c[1]} 50%, ${c[2]} 100%)`}}>
      <div style={{position: 'absolute', left: -220, top: -250, width: 940, height: 940, borderRadius: 940, background: 'radial-gradient(circle, rgba(255,222,160,0.17), transparent 64%)'}} />
      <svg width={1080} height={1920} style={{position: 'absolute', opacity: 0.1}}>
        {Array.from({length: 22}).map((_, i) => <line key={i} x1={0} y1={i * 90} x2={1080} y2={i * 90 + 40} stroke="#9cc2ff" strokeWidth={2} />)}
      </svg>
      {Array.from({length: 8}).map((_, i) => {
        const r = 90 + ((i * 59) % 120);
        return <div key={i} style={{position: 'absolute', left: ((i * 257) % 1160) - 60 + Math.sin(s * 0.33 + i) * 30, top: ((i * 401) % 1900) + Math.cos(s * 0.28 + i) * 40, width: r, height: r, borderRadius: r, background: i % 3 ? 'rgba(130,170,255,0.09)' : 'rgba(255,200,61,0.09)', filter: 'blur(24px)'}} />;
      })}
      <AbsoluteFill style={{background: 'radial-gradient(circle at 50% 50%, transparent 50%, rgba(0,0,0,0.66) 100%)'}} />
    </AbsoluteFill>
  );
};

// Contrato con firma que se dibuja
const Contrato: React.FC<{x: number; y: number}> = ({x, y}) => {
  const {s, spr, lin} = useS();
  const e = 0.85 + 0.15 * spr(-0.25, 12, 160) + 0.06 * Math.sin(s * 2.2) * (1 - spr(T_FIRMAR, 20, 80));
  const traza = lin(T_FIRMAS, T_FIRMAS + 0.6, 0, 1);
  const brillo = lin(T_FIRMA2 - 0.1, T_FIRMA2 + 0.3, 0, 1) * (1 - lin(T_CONTRATO + 0.6, T_CONTRATO + 1, 0, 1));
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute'}}>
      <defs>
        <linearGradient id="papelG" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#ffffff" />
          <stop offset="100%" stopColor="#c6cfe2" />
        </linearGradient>
      </defs>
      <g transform={`translate(${x} ${y}) scale(${e}) rotate(${-4 + Math.sin(s * 0.8) * 1.2})`}>
        <rect x={-180} y={-230} width={380} height={480} rx={16} fill="rgba(0,0,0,0.35)" style={{filter: 'blur(10px)'}} />
        <rect x={-190} y={-240} width={380} height={480} rx={16} fill="url(#papelG)" stroke={brillo > 0.2 ? ORO : '#8e9bb8'} strokeWidth={brillo > 0.2 ? 10 : 5} />
        {Array.from({length: 7}).map((_, i) => <rect key={i} x={-150} y={-190 + i * 44} width={i % 3 === 2 ? 180 : 300} height={14} rx={7} fill="#b2bdd6" />)}
        <text x={0} y={-200} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={44} fill="#2a3a66">$15,000</text>
        <line x1={-150} y1={170} x2={150} y2={170} stroke="#2a3a66" strokeWidth={4} />
        <path d="M -140 160 C -100 100 -80 200 -40 140 C -10 100 20 190 60 130 C 90 100 110 170 140 140" stroke="#1d3fbf" strokeWidth={8} fill="none" strokeLinecap="round" strokeDasharray="600" strokeDashoffset={600 * (1 - traza)} />
        <rect x={-180} y={-232} width={30} height={460} rx={14} fill="rgba(255,255,255,0.5)" />
      </g>
    </svg>
  );
};

// Monstruo de la deuda: crece con recargos, tiene cara y se enoja
const Monstruo: React.FC = () => {
  const {s, spr, lin} = useS();
  const nace = spr(T_DEJA - 0.1, 9, 140);
  const crece = 1 + 0.35 * spr(T_RECARGOS, 8, 150) + 0.15 * spr(T_COBRANZA, 8, 150);
  const salto = lin(T_DIRECTO - 0.05, T_DIRECTO + 0.45, 0, 1, Easing.inOut(Easing.cubic));
  const x = 300 + 300 * salto;
  const y = 1150 - Math.sin(salto * Math.PI) * 260;
  const enojo = lin(T_COMPLETA - 0.1, T_COMPLETA + 0.3, 0, 1);
  const respira = 1 + 0.04 * Math.sin(s * 4);
  if (nace <= 0.001) return null;
  const k = nace * crece * respira;
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute'}}>
      <defs>
        <radialGradient id="monsG" cx="35%" cy="30%" r="75%">
          <stop offset="0%" stopColor="#ff9c9c" />
          <stop offset="55%" stopColor={ROJO} />
          <stop offset="100%" stopColor="#8e1d1d" />
        </radialGradient>
      </defs>
      <ellipse cx={x + 10} cy={1400} rx={210 * k} ry={30} fill="rgba(0,0,0,0.4)" style={{filter: 'blur(10px)'}} />
      <g transform={`translate(${x} ${y}) scale(${k})`}>
        <path d="M -190 120 C -230 -60 -120 -200 0 -200 C 130 -200 230 -70 190 120 L 150 90 L 110 130 L 70 92 L 30 132 L -10 92 L -50 132 L -90 92 L -130 130 Z" fill="url(#monsG)" stroke="#6e1212" strokeWidth={8} />
        <path d={`M -100 -70 L -40 ${-50 + 20 * enojo}`} stroke="#3a0b0b" strokeWidth={14} strokeLinecap="round" />
        <path d={`M 100 -70 L 40 ${-50 + 20 * enojo}`} stroke="#3a0b0b" strokeWidth={14} strokeLinecap="round" />
        <circle cx={-65} cy={-20} r={20} fill="#fff" />
        <circle cx={65} cy={-20} r={20} fill="#fff" />
        <circle cx={-60} cy={-16} r={10} fill="#3a0b0b" />
        <circle cx={70} cy={-16} r={10} fill="#3a0b0b" />
        <path d="M -70 50 Q 0 100 70 50 L 50 60 L 35 40 L 15 62 L 0 42 L -15 62 L -35 40 L -50 60 Z" fill="#3a0b0b" />
        <ellipse cx={-90} cy={-150} rx={50} ry={20} fill="rgba(255,255,255,0.45)" />
      </g>
    </svg>
  );
};

// Cadena dorada desde el contrato hasta ti
const Cadena: React.FC<{x1: number; y1: number; x2: number; y2: number}> = ({x1, y1, x2, y2}) => {
  const {s, lin} = useS();
  const p = lin(T_ATADA - 0.1, T_ATADA + 0.5, 0, 1, Easing.out(Easing.cubic));
  if (p <= 0) return null;
  const n = 14;
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute'}}>
      {Array.from({length: n}).map((_, i) => {
        const t = i / (n - 1);
        if (t > p) return null;
        const x = x1 + (x2 - x1) * t;
        const y = y1 + (y2 - y1) * t + Math.sin(t * Math.PI) * 80 + Math.sin(s * 3 + i) * 4;
        return <ellipse key={i} cx={x} cy={y} rx={i % 2 ? 26 : 16} ry={i % 2 ? 16 : 26} fill="none" stroke={ORO} strokeWidth={9} />;
      })}
    </svg>
  );
};

// Hoja de historial con sello rojo
const Historial: React.FC = () => {
  const {spr} = useS();
  const e = spr(T_HISTORIAL - 0.2, 12, 170);
  const sello = spr(T_HISTORIAL + 0.15, 7, 260);
  if (e <= 0.001) return null;
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute'}}>
      <g transform={`translate(790 860) scale(${e}) rotate(6)`}>
        <rect x={-150} y={-190} width={300} height={380} rx={14} fill="#eef2fb" stroke="#8e9bb8" strokeWidth={5} />
        {Array.from({length: 6}).map((_, i) => <rect key={i} x={-110} y={-140 + i * 46} width={i % 2 ? 150 : 220} height={14} rx={7} fill="#b2bdd6" />)}
        <g transform={`scale(${sello}) rotate(-16)`} opacity={Math.min(1, sello)}>
          <circle r={95} fill="none" stroke={ROJO} strokeWidth={14} />
          <circle r={70} fill="rgba(255,77,77,0.25)" />
          <path d="M -40 -40 L 40 40 M 40 -40 L -40 40" stroke={ROJO} strokeWidth={16} strokeLinecap="round" />
        </g>
      </g>
    </svg>
  );
};

// Teléfono que avisa
const Telefono: React.FC = () => {
  const {s, spr} = useS();
  const e = spr(T_AVISEN - 0.15, 10, 180);
  if (e <= 0.001) return null;
  const vib = golpe(s, T_AVISEN + 0.1, 40, 4) * 12;
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute'}}>
      <g transform={`translate(${800 + vib} 1040) scale(${e}) rotate(8)`}>
        <rect x={-95} y={-180} width={190} height={360} rx={30} fill="#1d2440" stroke="#0a0f22" strokeWidth={8} />
        <rect x={-78} y={-150} width={156} height={290} rx={12} fill="#3a6fd8" />
        <circle cx={0} cy={-20} r={44} fill={ORO} />
        <path d="M -20 -10 Q -20 -50 0 -50 Q 20 -50 20 -10 L 26 6 L -26 6 Z" fill="#5a3b1d" />
        <rect x={-70} y={-145} width={24} height={270} rx={12} fill="rgba(255,255,255,0.25)" />
      </g>
    </svg>
  );
};

const Avion: React.FC = () => {
  const {lin} = useS();
  const p = lin(T_ENVIA + 0.1, T_ENVIA + 1.6, 0, 1, Easing.in(Easing.quad));
  if (p <= 0 || p >= 1) return null;
  return (
    <svg width={170} height={170} viewBox="0 0 100 100" style={{position: 'absolute', left: 520 + p * 560, top: 1200 - p * 850 - Math.sin(p * Math.PI) * 150, transform: `rotate(-28deg) scale(${1.1 - p * 0.5})`}}>
      <polygon points="5,50 95,10 60,90 48,58" fill="#ffffff" />
      <polygon points="48,58 95,10 40,70" fill="#b9c8ea" />
    </svg>
  );
};

export const Escena: React.FC = () => {
  const {s, lin, spr} = useS();
  const enB = s >= T_DEJA - 0.02 && s < T_FIRMA2 - 0.02;
  const sh = sacudida(s, [T_COMPLETA, T_DIRECTO + 0.45, T_HISTORIAL + 0.15], 14);
  const deriva = Math.sin(s * 0.5) * 12;
  // personajes: primo a la izquierda, tú a la derecha
  const susto = s > T_DIRECTO + 0.3 && s < T_FIRMA2;
  const paradasA = [
    {t: 0, x: 540, y: 1100, zoom: 1.05},
    {t: T_CARO, x: 560, y: 1080, zoom: 1.15},
    {t: T_PRIMO + 0.3, x: 300, y: 1150, zoom: 1.35},
    {t: T_FIRMAS + 0.4, x: 540, y: 1000, zoom: 1.3},
    {t: T_ATADA + 0.5, x: 620, y: 1080, zoom: 1.1},
    {t: T_DEJA, x: 600, y: 1100, zoom: 1.2},
  ];
  const paradasB = [
    {t: T_DEJA, x: 540, y: 1150, zoom: 1.0},
    {t: T_COMPLETA + 0.3, x: 500, y: 1130, zoom: 1.25},
    {t: T_DIRECTO + 0.5, x: 700, y: 1150, zoom: 1.35},
    {t: T_RECARGOS + 0.6, x: 600, y: 1100, zoom: 1.0},
    {t: T_HISTORIAL + 0.4, x: 700, y: 980, zoom: 1.25},
  ];
  const paradasC = [
    {t: T_FIRMA2, x: 540, y: 1050, zoom: 1.1},
    {t: T_QUINCE2 + 0.4, x: 540, y: 1000, zoom: 1.35},
    {t: T_AVISEN + 0.3, x: 700, y: 1050, zoom: 1.2},
    {t: T_FAMILIA + 1, x: 540, y: 1080, zoom: 0.95},
  ];
  const dibujoA = (
    <>
      <Contrato x={540} y={980} />
      <Carita x={250} y={1420} size={300} color={['#ffe0a3', '#ffb347', '#e0782a']} saltos={[T_PRIMO, T_CARRO]} boca="feliz" />
      <Carita x={830} y={1420} size={300} color={['#cfe3ff', '#7fb2ff', '#3a6fd8']} saltos={[T_FIRMAS, T_ATADA]} boca={s > T_ATADA ? 'o' : 'feliz'} />
      <Cadena x1={640} y1={1180} x2={830} y2={1290} />
    </>
  );
  return (
    <AbsoluteFill>
      <FondoSitio oscuro={enB} />
      {enB && <AbsoluteFill style={{background: `radial-gradient(circle at 40% 85%, rgba(255,77,77,${0.18 * lin(T_COMPLETA, T_COMPLETA + 0.5, 0, 1)}), transparent 60%)`}} />}
      <AbsoluteFill style={{transform: `translate(${sh.x + deriva}px, ${sh.y}px)`}}>
        {s < T_DEJA - 0.02 && <Camara paradas={paradasA} centroY={1080}>{dibujoA}</Camara>}
        {enB && (
          <Camara paradas={paradasB} centroY={1080}>
            <Carita x={170} y={1500} size={220} color={['#ffe0a3', '#ffb347', '#e0782a']} saltos={[T_DEJA]} boca="triste" />
            <Carita x={880} y={1450} size={300} color={['#cfe3ff', '#7fb2ff', '#3a6fd8']} saltos={[T_COMPLETA, T_DIRECTO + 0.45, T_HISTORIAL + 0.15]} boca={susto ? 'o' : 'triste'} />
            <Estela t0={T_DIRECTO} t1={T_DIRECTO + 0.5} copias={4} render={(t, al) => (
              <div style={{position: 'absolute', left: 300 + 300 * interpolate(t, [T_DIRECTO - 0.05, T_DIRECTO + 0.45], [0, 1], clamp) - 150, top: 1050, width: 300, height: 260, borderRadius: 150, background: ROJO, opacity: al}} />
            )} />
            <Monstruo />
            <Historial />
            <Ondas x={880} y={1450} t0={T_DIRECTO + 0.45} color={ROJO} />
          </Camara>
        )}
        {s >= T_FIRMA2 - 0.02 && (
          <Camara paradas={paradasC} centroY={1080}>
            <Contrato x={420} y={980} />
            <Carita x={830} y={1450} size={300} color={['#cfe3ff', '#7fb2ff', '#3a6fd8']} saltos={[T_QUINCE2, T_ENVIA + 0.2]} boca="feliz" />
            <Telefono />
            <Ondas x={800} y={1040} t0={T_AVISEN + 0.1} color={ORO} />
          </Camara>
        )}
        <Avion />
      </AbsoluteFill>
      {s >= T_QUINCE && s < T_ATADA && <Contador desde={0} hasta={15000} t0={T_QUINCE} t1={T_CARRO + 0.3} y={430} prefijo="$" color={ORO} />}
      {s >= T_COMPLETA && s < T_RECARGOS && <Contador desde={0} hasta={15000} t0={T_COMPLETA} t1={T_COMPLETA + 0.7} y={430} prefijo="$" color={ROJO} />}
      {s >= T_RECARGOS && s < T_HISTORIAL && <Etiqueta texto="+ $" x={540} y={440} px={430} py={900} t0={T_RECARGOS} color={ROJO} size={60} />}
      {s >= T_QUINCE2 && s < T_AVISEN && <Contador desde={0} hasta={15000} t0={T_QUINCE2} t1={T_QUINCE2 + 0.7} y={430} prefijo="$" color={ORO} />}
      <Destello t0={T_COMPLETA} fuerza={0.25} />
      <Destello t0={T_DIRECTO + 0.45} fuerza={0.35} />
      <AbsoluteFill style={{pointerEvents: 'none', background: `radial-gradient(circle at 50% 60%, rgba(255,200,61,${0.07 * spr(T_FIRMA2, 14, 120)}), transparent 60%)`}} />
    </AbsoluteFill>
  );
};
